def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    dangerous_pressure = 0.0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                req = opp.get('water_requirement', WATER_REQ)
                if req <= supply:
                    dangerous_pressure = max(dangerous_pressure, bid)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    urgency = 0.0
    if hp <= 2:
        urgency += 1.2
    elif hp <= 4:
        urgency += 0.7
    elif hp <= 6:
        urgency += 0.35

    if no_water_days >= 2:
        urgency += 1.0
    elif no_water_days == 1:
        urgency += 0.45

    urgency += 0.55 * scarcity

    if prev_bids:
        avg_prev = sum(prev_bids) / float(len(prev_bids))
        max_prev = max(prev_bids)
    else:
        avg_prev = 0.0
        max_prev = 0.0

    if supply >= 23:
        base = 10.0
    elif supply >= 20:
        base = 18.0
    elif supply >= 17:
        base = 28.0
    else:
        base = 40.0

    if urgency >= 1.6:
        bid = max(base + 20.0, avg_prev * 0.72 + 6.0)
    elif urgency >= 0.9:
        bid = max(base + 8.0, avg_prev * 0.5 + 4.0)
    else:
        if max_prev >= 120:
            bid = base * 0.55
        elif max_prev >= 90:
            bid = base * 0.75
        else:
            bid = max(base, avg_prev * 0.38 + 3.0)

    if dangerous_pressure >= 140 and urgency < 1.6:
        bid *= 0.75
    elif dangerous_pressure <= 40 and urgency >= 0.9:
        bid = max(bid, dangerous_pressure + 3.0, 26.0)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, 52.0)
    elif hp <= 4:
        bid = max(bid, 34.0)

    if budget < DAILY_SALARY:
        bid = min(bid, budget * 0.82)
    else:
        reserve_target = DAILY_SALARY * 2.2
        if budget < reserve_target and urgency < 1.0:
            bid = min(bid, DAILY_SALARY * 0.55)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    current_bid = DAILY_SALARY * 0.65

    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        current_bid = DAILY_SALARY * 0.95
    elif day_context['day'] >= EPISODE_DAYS - 2:
        current_bid = DAILY_SALARY * 0.85

    highest_prev_bid = 0.0
    bob_highest_bid_yesterday = False

    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                opp_bid = prev['bid']
                if opp_bid > highest_prev_bid:
                    highest_prev_bid = opp_bid
                    bob_highest_bid_yesterday = (opp_id == "Bob")
                elif opp_bid == highest_prev_bid and opp_id == "Bob":
                    bob_highest_bid_yesterday = True

    if highest_prev_bid > 0:
        if bob_highest_bid_yesterday and highest_prev_bid >= DAILY_SALARY * 0.8:
            current_bid = max(current_bid, highest_prev_bid + 5)
        elif highest_prev_bid >= DAILY_SALARY * 0.7:
            current_bid = max(current_bid, highest_prev_bid + 3)
        else:
            current_bid = max(current_bid, highest_prev_bid + 1)

    return min(my_status['budget'], current_bid)

